/usr/bin/zsh -lc "node --input-type=module - <<'NODE'
import {readFileSync} from 'node:fs';
import {execFileSync} from 'node:child_process';
const test = readFileSync('src/transport/ws/messageHandler.test.ts','utf8').split('\\n');
const hits = execFileSync('rg',['-n','messageHandler\\\\.test\\\\.ts#L','specs'],{encoding:'utf8'}).trim().split('\\n');
for (const hit of hits) {
  const links = [...hit.matchAll(/\\[validated by: (["'^'"\\]]+)\\]\\(\\.\\.\\/\\.\\.\\/src\\/transport\\/ws\\/messageHandler\\.test\\.ts#L(\\d+)\\)/g)];
  for (const [,title,old] of links) {
    const at = test.findIndex(line => line.includes("'`it('"'"'${title.replaceAll("'"'\", \"\\\\'\")}'"'`));
    if (at >= 0 && String(at + 1) !== old) console.log(`${old}->${at+1}'"\\t"'${title}`);
  }
}
NODE'
